import{_ as s,o as t,c as e,a2 as p}from"./chunks/framework.F7eQ-ohH.js";const o="/bzygq/assets/quesion_imgs_00b2a49ad2d7429f9c552813245959b1.BlEwrVk4.png",r="/bzygq/assets/quesion_imgs_03e111772af2427b929f6a8ea6fd8900.Bp_QKSu7.png",_="/bzygq/assets/quesion_imgs_5a661cfafe2c412d99f75918591a11cf.BDs0_qwu.png",n="/bzygq/assets/quesion_imgs_e74f5fce8b9d4849a557fe0edc20aefd.CP10Yjcv.png",i="/bzygq/assets/quesion_imgs_a0714f144b03410e9a22bb8470d2e9fc.UBhNyTSt.png",c="/bzygq/assets/quesion_imgs_42d055de30394c02ac8f46efe22a24ce.CPet_n30.png",u=JSON.parse('{"title":"什么是整体部分数？","description":"","frontmatter":{},"headers":[],"relativePath":"行测/逻辑推理/1.图形推理/11.整体和部分数.md","filePath":"行测/逻辑推理/1.图形推理/11.整体和部分数.md","lastUpdated":1788883925000}'),d={name:"行测/逻辑推理/1.图形推理/11.整体和部分数.md"};function g(l,a,m,f,h,b){return t(),e("div",null,[...a[0]||(a[0]=[p('<h1 id="什么是整体部分数" tabindex="-1">什么是整体部分数？ <a class="header-anchor" href="#什么是整体部分数" aria-label="Permalink to &quot;什么是整体部分数？&quot;">​</a></h1><p>行测中的“图形推理——整体和部分”题型主要考察的是考生对图形中整体与部分关系的理解和识别能力，一般来说整体部分数都是考察一个大图形由多少个独立子图构成的，一般有以下两类题。</p><h2 id="普通几何图形" tabindex="-1">普通几何图形 <a class="header-anchor" href="#普通几何图形" aria-label="Permalink to &quot;普通几何图形&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>如上图所示，图形大图形整体由两个小的部分组成，更准确一点儿来说，大图形是由两个子连通图构成的。</p><h2 id="黑白块" tabindex="-1">黑白块 <a class="header-anchor" href="#黑白块" aria-label="Permalink to &quot;黑白块&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>黑白块题型也可以考察整体部分数，这个优点像围棋，比如下图就考察黑子将白字分割成了多少个部分数，然后可以将以下6个图形分成2类。</p><h1 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h1><p><strong>例题1：请从所给的四个选项中，选出最恰当的一项填入问号处，使之呈现一定的规律性。</strong></p><p><img src="'+_+'" alt=""></p><p>解析：观察发现题干出现较多生活化图形，考虑部分数。题干图形的部分数均为2，故？处要选一个部分数为2的图形，只有B项符合。</p><p><strong>例题2：从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：</strong></p><p><img src="'+n+'" alt=""></p><p>解析：整体观察题干，图形元素构成凌乱，考虑数量。观察发现，每个图形均由两个部分构成，满足这一规律的只有B项。</p><p><strong>例题3：从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：</strong></p><p><img src="'+i+'" alt=""></p><p>解析：整体观察题干，图形元素构成凌乱，考虑整体和部分数，均为2部分，选项A满足规律。</p><p><strong>例题4：把下面的六个图形分为两类，使每一类图形都有各自的共同特征和规律，分类正确的一项是：</strong></p><p><img src="'+c+'" alt=""></p><p>A.①②⑥，③④⑤ B.①③④，②⑤⑥</p><p>C.①⑤⑥，②③④ D.①③⑤，②④⑥</p><p>解析：题干图形出现了粗线条和生活化图形，考虑部分数。图①③⑤的部分数均为1，图②④⑥的部分数均为2。故图①③⑤为一组，图②④⑥为一组。故正确答案为D。</p>',23)])])}const P=s(d,[["render",g]]);export{u as __pageData,P as default};
